import{_ as i,o as e,c as l,a0 as t}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"webpack 简介","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/1-preface.md","filePath":"webpack/1-preface.md","lastUpdated":1791573371000}'),o={name:"webpack/1-preface.md"};function r(p,a,s,c,n,u){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="webpack-简介" tabindex="-1">webpack 简介 <a class="header-anchor" href="#webpack-简介" aria-label="Permalink to &quot;webpack 简介&quot;">​</a></h1><h2 id="_1-webpack-的由来" tabindex="-1">1 webpack 的由来 <a class="header-anchor" href="#_1-webpack-的由来" aria-label="Permalink to &quot;1 webpack 的由来&quot;">​</a></h2><h4 id="作者-tobias-koppers-github-sokra" tabindex="-1">作者：Tobias Koppers （github: @sokra） <a class="header-anchor" href="#作者-tobias-koppers-github-sokra" aria-label="Permalink to &quot;作者：Tobias Koppers （github: @sokra）&quot;">​</a></h4><p>It’s a funny story how I started with Webpack. Before getting addicted to JavaScript, I also developed in Java. I tried GWT (Google Web Toolkit) in that time. GWT is a Java-to-JavaScript Compiler, which has a great feature: code-splitting. I liked this feature and missed it in existing JavaScript tooling. I made a pull request to an existing module bundler, but it did not go through. Webpack was born.</p><h2 id="_2-前后端分工演变" tabindex="-1">2 前后端分工演变 <a class="header-anchor" href="#_2-前后端分工演变" aria-label="Permalink to &quot;2 前后端分工演变&quot;">​</a></h2><p><strong>很久以前</strong></p><p>前端：</p><ul><li>View</li><li>View Logic</li></ul><p>后端：</p><ul><li>Router</li><li>Render</li><li>Data logic</li><li>Data base</li></ul><p><strong>现在</strong></p><p>前端：</p><ul><li>View</li><li>Router</li><li>View logic</li><li>Render</li><li>Data logic</li></ul><p>后端：</p><ul><li>Data logic</li><li>API</li><li>Data base</li></ul><h2 id="_3-前端框架演变" tabindex="-1">3 前端框架演变 <a class="header-anchor" href="#_3-前端框架演变" aria-label="Permalink to &quot;3 前端框架演变&quot;">​</a></h2><p><code>js库 =&gt; mvc =&gt; mvvm</code></p><p>js 库：</p><ul><li>dojo</li><li>yui</li><li>jQuery</li><li>prototype</li><li>mootools</li><li>kissy</li></ul><p>mvc：</p><ul><li>backbone.js</li></ul><p>mvvm：</p><ul><li>angular</li><li>vue</li><li>react</li></ul><h2 id="_3-工具的发展" tabindex="-1">3 工具的发展 <a class="header-anchor" href="#_3-工具的发展" aria-label="Permalink to &quot;3 工具的发展&quot;">​</a></h2><ul><li>apache ant 将软件编译、测试、部署等步骤联系在一起加以自动化的一个工具，大多用于Java环境中的软件开发</li><li>grunt 自动化处理任务的构建工具</li><li>gulp 同上，配置更简单，速度更快</li><li>webpack 模块打包器</li></ul><h2 id="_4-为什么需要构建工具" tabindex="-1">4 为什么需要构建工具 <a class="header-anchor" href="#_4-为什么需要构建工具" aria-label="Permalink to &quot;4 为什么需要构建工具&quot;">​</a></h2><ul><li>开发复杂</li><li>框架去中心化</li><li>语言编译化</li><li>开发模块化</li></ul>',27)])])}const b=i(o,[["render",r]]);export{h as __pageData,b as default};
